    # 4. P-512 Gauss Digamma Closed Forms for c^infty(3/8) and c^infty(1/8):
    mp.mp.dps = 35
    c_inf_3_8_digamma = float(
        -mp.euler - mp.log(2 * mp.pi) - (mp.digamma(mp.mpf(3) / 8) + mp.digamma(mp.mpf(5) / 8)) / 2
    ) * 2.0 * math.pi
