            float(np.max(np.abs(sv_e0 - sv_d0) / sv_d0)),
            abs(abs(complex(np.linalg.det(ye_0))) - abs(complex(np.linalg.det(yd_0)))) / abs(complex(np.linalg.det(yd_0))),
