    t_mp = mp.mpf("1.37") * mp.exp(1j * mp.mpf("0.41"))
    t3_mp = t_mp ** 3
    w_ad_mp = lambda z_v: -(z_v ** -2) * (z_v - 1) * (z_v - 5 + (1 / z_v))
